・コロナ放電：気圧が低い・湿度が高い（雨天）ほど発生しやすい★
・中性点接地方式：非接地（小規模配電）／直接接地（超高圧）／
　抵抗接地／消弧リアクトル接地（地絡アーク電流を消弧）★
