━━━━━━━━━━━━━━━━━━━━━━
【図解】消防設備士と届出
　甲種消防設備士：工事＋整備○★
　乙種消防設備士：整備のみ（工事は不可×）★
　自動火災報知設備の工事＝甲種第4類★
