　設置届：完了後4日以内・防火対象物の関係者が届出★

・感知器：差動式＝温度上昇率／定温式＝一定温度★
　（厨房・ボイラー室は定温式★）
・非常電源回路：耐火・耐熱配線で一般回路と別系統★
・誘導灯非常電源：20分（大規模・高層60分）★
・消防用設備等の点検：機器点検6か月ごと・
